"*/\n"
"/* Vulkan compute/coverage adapter: djultra64. Fixed MODE0 profile matches sprite_xbr.c. */\n"
"\n"
"#ifndef FINAL_RGBA8\n"
"#define FINAL_RGBA8 0\n"
"#endif\n"
"layout(local_size_x=8,local_size_y=8,local_size_z=1) in;\n"
"layout(constant_id=0) const uint PHASE=0u;\n"
"layout(set=0,binding=0) uniform sampler2D Original;\n"
"layout(set=0,binding=1) uniform sampler2D FilterInput;\n"
"#if FINAL_RGBA8\n"
"layout(set=0,binding=2,rgba8) uniform writeonly image2D Destination;\n"
"#else\n"
"layout(set=0,binding=2,rgba32f) uniform writeonly image2D Destination;\n"
"#endif\n"
"layout(push_constant) uniform Parameters {uint outWidth;uint outHeight;uint originalPremult;uint reserved;} pc;\n"
"// BEGIN_CPU_COMPATIBLE_KERNEL\n"
"struct Pixel {vec4 v;};\n"
"const ivec2 OFF[16]=ivec2[16](ivec2(-1,-1),ivec2(2,-1),ivec2(-1,2),ivec2(2,2),ivec2(0,-1),ivec2(1,-1),ivec2(-1,0),ivec2(0,0),ivec2(1,0),ivec2(-1,1),ivec2(0,1),ivec2(1,1),ivec2(2,0),ivec2(2,1),ivec2(0,2),ivec2(1,2));\n"
"const int P0=0,P1=1,P2=2,P3=3,B=4,C=5,D=6,E=7,F=8,G=9,H=10,I=11,F4=12,I4=13,H5=14,I5=15;\n"
"float smin(float a,float b){return a<b?a:b;}\n"
"float smax(float a,float b){return a>b?a:b;}\n"
"float sclip(float x,float a,float b){return smin(smax(x,a),b);}\n"
"float df(float a,float b){return abs(a-b);}\n"
"float dwd(float w[6],float b0,float b1,float c0,float c1,float c2,float d0,float d1,float d2,float d3,float e1,float e2,float e3,float f2,float f3){\n"
" return w[0]*(df(c1,c2)+df(c1,c0)+df(e2,e1)+df(e2,e3))+w[1]*(df(d2,d3)+df(d0,d1))+w[2]*(df(d1,d3)+df(d0,d2))+w[3]*df(d1,d2)+w[4]*(df(c0,c2)+df(e1,e3))+w[5]*(df(b0,b1)+df(f2,f3));\n"
"}\n"
"float hvwd(float w[6],float i1,float i2,float i3,float i4,float e1,float e2,float e3,float e4){return w[3]*(df(i1,i2)+df(i3,i4))+w[0]*(df(i1,e1)+df(i2,e2)+df(i3,e3)+df(i4,e4))+w[2]*(df(i1,e2)+df(i3,e4)+df(e1,i2)+df(e3,i4));}\n"
"float weighted(float a,float b,float c,float d,float q,float middle){return a*(-q)+b*(q+middle)+c*(q+middle)+d*(-q);}\n"
"Pixel filtered(Pixel p[16],uint phase){\n"
" precise float w[6];\n"
" if(phase==0u){w[0]=2;w[1]=1;w[2]=-1;w[3]=4;w[4]=-1;w[5]=1;}\n"
" else if(phase==1u){w[0]=8;w[1]=0;w[2]=0;w[3]=0;w[4]=0;w[5]=0;}\n"
" else{w[0]=1;w[1]=0;w[2]=2;w[3]=3;w[4]=-2;w[5]=1;}\n"
" precise float m[16];for(uint k=0u;k<16u;k++)m[k]=p[k].v[0]*.2126f+p[k].v[1]*.7152f+p[k].v[2]*.0722f+(p[k].v[3]-1.f);\n"
" precise float de=dwd(w,m[D],m[B],m[G],m[E],m[C],m[P2],m[H],m[F],m[P1],m[H5],m[I],m[F4],m[I5],m[I4])-dwd(w,m[C],m[F4],m[B],m[F],m[I4],m[P0],m[E],m[I],m[P3],m[D],m[H],m[I5],m[G],m[H5]);\n"
" precise float hv=hvwd(w,m[F],m[I],m[E],m[H],m[C],m[I5],m[B],m[H5])-hvwd(w,m[E],m[F],m[H],m[I],m[D],m[F4],m[G],m[I4]);\n"
" precise float t=sclip(abs(de)/(.6f+.000001f),0,1);t=t*t*(3-2*t);\n"
" precise float a=phase==1u?.175068f:.129633f,b=phase==1u?.0648165f:.087534f;Pixel result;\n"
" for(uint c=0u;c<4u;c++){\n"
"  precise float c1=weighted(p[P2].v[c],p[H].v[c],p[F].v[c],p[P1].v[c],a,.5f);\n"
"  precise float c2=weighted(p[P0].v[c],p[E].v[c],p[I].v[c],p[P3].v[c],a,.5f);\n"
"  precise float c3=weighted(p[D].v[c]+p[G].v[c],p[E].v[c]+p[H].v[c],p[F].v[c]+p[I].v[c],p[F4].v[c]+p[I4].v[c],b,.25f);\n"
"  precise float c4=weighted(p[C].v[c]+p[B].v[c],p[F].v[c]+p[E].v[c],p[I].v[c]+p[H].v[c],p[I5].v[c]+p[H5].v[c],b,.25f);\n"
"  precise float q=(de>=0?c2:c1)*t+(hv>=0?c4:c3)*(1-t);\n"
"  precise float mn=smin(smin(p[E].v[c],p[F].v[c]),smin(p[H].v[c],p[I].v[c]));\n"
"  precise float mx=smax(smax(p[E].v[c],p[F].v[c]),smax(p[H].v[c],p[I].v[c]));result.v[c]=sclip(q,mn,mx);\n"
" }\n"
" result.v[3]=sclip(result.v[3],0,1);for(uint c=0u;c<3u;c++)result.v[c]=sclip(result.v[c],0,result.v[3]);return result;\n"
"}\n"
"Pixel original(vec2 at){\n"
" ivec2 size=textureSize(Original,0);ivec2 xy=clamp(ivec2(floor(at)),ivec2(0),size-ivec2(1));\n"
" Pixel p;p.v=texelFetch(Original,xy,0);\n"
" if(pc.originalPremult==0u)for(uint c=0u;c<3u;c++)p.v[c]*=p.v[3];return p;\n"
"}\n"
"Pixel inputPixel(vec2 at){\n"
" ivec2 size=textureSize(FilterInput,0);ivec2 xy=clamp(ivec2(floor(at)),ivec2(0),size-ivec2(1));Pixel p;p.v=texelFetch(FilterInput,xy,0);return p;\n"
"}\n"
"Pixel computePixel(ivec2 xy){\n"
" Pixel p[16];vec2 at=vec2(xy);\n"
" if(PHASE!=1u){for(uint k=0u;k<16u;k++){\n"
"  vec2 point=at+vec2(OFF[k])-vec2(PHASE==2u?1:0);\n"
"  p[k]=PHASE==0u?original(point):inputPixel(point);\n"
" }return filtered(p,PHASE);}\n"
" uint x=uint(xy.x),y=uint(xy.y);precise float u=(float(x)+.5f)*.5f,v=(float(y)+.5f)*.5f;\n"
" if((x&1u)==(y&1u))return (x&1u)!=0u?inputPixel(vec2(u,v)):original(vec2(u,v));\n"
" precise float ax=(x&1u)!=0u?.5f:0,ay=(x&1u)!=0u?0:.5f,bx=(x&1u)!=0u?0:.5f,by=(x&1u)!=0u?.5f:0;\n"
" p[P0]=original(vec2(u-3*ax,v-3*ay));p[P1]=inputPixel(vec2(u-3*bx,v-3*by));p[P2]=inputPixel(vec2(u+3*bx,v+3*by));p[P3]=original(vec2(u+3*ax,v+3*ay));\n"
" p[B]=inputPixel(vec2(u-2*ax-bx,v-2*ay-by));p[C]=original(vec2(u-ax-2*bx,v-ay-2*by));p[D]=inputPixel(vec2(u-2*ax+bx,v-2*ay+by));p[E]=original(vec2(u-ax,v-ay));\n"
" p[F]=inputPixel(vec2(u-bx,v-by));p[G]=original(vec2(u-ax+2*bx,v-ay+2*by));p[H]=inputPixel(vec2(u+bx,v+by));p[I]=original(vec2(u+ax,v+ay));\n"
" p[F4]=original(vec2(u+ax-2*bx,v+ay-2*by));p[I4]=inputPixel(vec2(u+2*ax-bx,v+2*ay-by));p[H5]=original(vec2(u+ax+2*bx,v+ay+2*by));p[I5]=inputPixel(vec2(u+2*ax+bx,v+2*ay+by));return filtered(p,1u);\n"
"}\n"
"vec4 straightBytes(Pixel p){\n"
" vec4 q;q[3]=floor(sclip(p.v[3],0,1)*255.f+.5f);\n"
" for(uint c=0u;c<3u;c++)q[c]=floor(sclip(p.v[3]>0?p.v[c]/p.v[3]:0,0,1)*255.f+.5f);return q;\n"
"}\n"
"vec4 finalPixel(ivec2 xy){\n"
" vec4 q=straightBytes(computePixel(xy));\n"
" if(q[3]==0){float highest=0;\n"
"  for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){\n"
"   ivec2 pos=xy+ivec2(dx,dy);if(pos.x<0||pos.y<0||pos.x>=int(pc.outWidth)||pos.y>=int(pc.outHeight))continue;\n"
"   vec4 neighbor=straightBytes(computePixel(pos));if(neighbor[3]>highest){highest=neighbor[3];for(uint c=0u;c<3u;c++)q[c]=neighbor[c];}\n"
"  }\n"
" }return q/255.f;\n"
"}\n"
"// END_CPU_COMPATIBLE_KERNEL\n"
"void main(){\n"
" ivec2 xy=ivec2(gl_GlobalInvocationID.xy);\n"
" if(xy.x>=int(pc.outWidth)||xy.y>=int(pc.outHeight))return;\n"
"#if FINAL_RGBA8\n"
" imageStore(Destination,xy,finalPixel(xy));\n"
"#else\n"
" imageStore(Destination,xy,computePixel(xy).v);\n"
"#endif\n"
"}\n"
;
